const { Window } = require('happy-dom');
const { setWorldConstructor } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');

const APP_HTML = fs.readFileSync(
  path.resolve(__dirname, '../../assets/app-template.index.html'),
  'utf-8'
);
const TODOMVC_CSS = fs.readFileSync(
  path.resolve(__dirname, '../../node_modules/todomvc-common/base.css'),
  'utf-8'
);
const APP_CSS = fs.readFileSync(
  path.resolve(__dirname, '../../node_modules/todomvc-app-css/index.css'),
  'utf-8'
);

const STORAGE_KEY = 'todos-javascript';

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  setupWindow(hash) {
    const win = new Window();
    win.location.href = 'http://localhost/' + (hash || '#/');
    win.document.write(APP_HTML);

    const styleBase = win.document.createElement('style');
    styleBase.textContent = TODOMVC_CSS;
    win.document.head.appendChild(styleBase);

    const styleApp = win.document.createElement('style');
    styleApp.textContent = APP_CSS;
    win.document.head.appendChild(styleApp);

    this.window = win;
    this.document = win.document;
    this.localStorage = win.localStorage;
    this.localStorage.clear();

    return win;
  }

  runAppCode() {
    const jsPath = path.resolve(__dirname, '../../js/app.js');
    if (fs.existsSync(jsPath)) {
      const appCode = fs.readFileSync(jsPath, 'utf-8');
      try {
        const win = this.window;
        const fn = new win.Function('window', 'document', 'localStorage', appCode);
        fn(win, win.document, win.localStorage);
      } catch (e) {
        throw new Error('App code execution failed: ' + e.message);
      }
    } else {
      throw new Error('js/app.js not found - production code missing');
    }
  }
}

setWorldConstructor(TodoWorld);

const { Given, When, Then, Before, After } = require('@cucumber/cucumber');
const assert = require('assert');

const STORAGE_KEY = 'todos-javascript';

// ----- Background helpers -----

function setupApp(world, hash) {
  const win = world.setupWindow(hash);
  world.runAppCode();
}

function getTodoList(world) {
  return world.document.querySelectorAll('.todo-list li');
}

function findTodoItem(world, title) {
  const items = getTodoList(world);
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      return item;
    }
  }
  return null;
}

function getTodoCountText(world) {
  const el = world.document.querySelector('.todo-count');
  return el ? el.textContent.trim() : '';
}

function serializeTodosFromDOM(world) {
  const items = getTodoList(world);
  const todos = [];
  for (const item of items) {
    const label = item.querySelector('label');
    const toggle = item.querySelector('.toggle');
    todos.push({
      title: label ? label.textContent.trim() : '',
      completed: toggle ? toggle.checked : false
    });
  }
  return todos;
}

function dispatchKeyEvent(world, element, key, code) {
  const event = new world.window.KeyboardEvent('keydown', {
    key,
    keyCode: code,
    which: code,
    bubbles: true,
    cancelable: true
  });
  element.dispatchEvent(event);
}

function dispatchBlurEvent(world, element) {
  const event = new world.window.Event('blur', { bubbles: true, cancelable: false });
  element.dispatchEvent(event);
}

function dispatchDblClickEvent(world, element) {
  const event = new world.window.MouseEvent('dblclick', {
    bubbles: true,
    cancelable: true,
    view: world.window
  });
  element.dispatchEvent(event);
}

function dispatchClickEvent(world, element) {
  const event = new world.window.MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    view: world.window
  });
  element.dispatchEvent(event);
}

function dispatchHashChangeEvent(world, oldURL, newURL) {
  const event = new world.window.HashChangeEvent('hashchange', {
    oldURL,
    newURL,
    bubbles: true,
    cancelable: true
  });
  world.window.dispatchEvent(event);
}

function seedLocalStorage(world, todos) {
  const stored = todos.map((t, i) => ({
    id: 'seed-' + i + '-' + Date.now(),
    title: t.title,
    completed: t.completed || false
  }));
  world.localStorage.setItem(STORAGE_KEY, JSON.stringify(stored));
}

function loadAppFromStorage(world, hash) {
  const win = world.setupWindow(hash || '#/');
  win.location.href = 'http://localhost/' + (hash || '#/');
  win.document.write(APP_HTML);
  const styleBase = win.document.createElement('style');
  styleBase.textContent = TODOMVC_CSS;
  win.document.head.appendChild(styleBase);
  const styleApp = win.document.createElement('style');
  styleApp.textContent = APP_CSS;
  win.document.head.appendChild(styleApp);
  world.window = win;
  world.document = win.document;
  world.localStorage = win.localStorage;
  world.runAppCode();
}

// ----- Cucumber hooks -----

Before(function () {
  if (this.window) {
    // noop - each given sets up fresh
  }
});

// ----- Given steps -----

Given('the app is loaded fresh', function () {
  setupApp(this, '#/');
});

Given('the application starts at the {string} route', function (route) {
  setupApp(this, route);
});

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map(r => ({
    title: r.title,
    completed: r.completed === 'true'
  }));
  seedLocalStorage(this, todos);
  // Re-load the app so it picks up the seeded localStorage
  loadAppFromStorage(this, this.window ? this.window.location.hash : '#/');
  // Trigger initial route after reload
  const hash = this.window.location.hash || '#/';
  dispatchHashChangeEvent(this, 'http://localhost/', 'http://localhost/' + hash);
});

// ----- When steps -----

When('the user types {string} into the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert(input, 'new-todo input not found');
  input.value = text;
  dispatchKeyEvent(this, input, 'Enter', 13);
});

When('the user clicks the toggle checkbox on {string}', function (title) {
  const item = findTodoItem(this, title);
  assert(item, 'Todo item "' + title + '" not found');
  const toggle = item.querySelector('.toggle');
  assert(toggle, 'Toggle checkbox not found for "' + title + '"');
  toggle.checked = !toggle.checked;
  dispatchClickEvent(this, toggle);
  // Trigger change event
  const changeEvent = new this.window.Event('change', { bubbles: true });
  toggle.dispatchEvent(changeEvent);
