  assert(targetLink, 'Filter link "' + filterName + '" not found');
  var newHash = targetLink.getAttribute('href');
  var oldURL = this.window.location.href;
  this.window.location.hash = newHash;
  dispatchClickEvent(this, targetLink);
  dispatchHashChangeEvent(this, oldURL, this.window.location.href);
});

When('the app is reloaded', function () {
  loadAppFromStorage(this, this.window.location.hash || '#/');
  var hash = this.window.location.hash || '#/';
