When('the app is reloaded again', function () {
  loadAppFromStorage(this, this.window.location.hash || '#/');
  var hash = this.window.location.hash || '#/';
  dispatchHashChangeEvent(this, 'http://localhost/', 'http://localhost/' + hash);
});

When('the user views the todo-count', function () {
  // No action needed
});

When('the user navigates back in browser history', function () {
  var currentHash = this.window.location.hash;
  var prevHash = '#/';
  if (currentHash === '#/active') {
    prevHash = '#/';
  } else if (currentHash === '#/completed') {
    prevHash = '#/active';
  }
  var oldURL = this.window.location.href;
  this.window.location.hash = prevHash;
  dispatchHashChangeEvent(this, oldURL, this.window.location.href);
});

