  world.runAppCode();
}

function getTodoList(world) {
  return world.document.querySelectorAll('.todo-list li');
}

function findTodoItem(world, title) {
  var items = getTodoList(world);
  for (var i = 0; i < items.length; i++) {
    var label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      return items[i];
    }
  }
  return null;
}

function getTodoCountText(world) {
  var el = world.document.querySelector('.todo-count');
  return el ? el.textContent.trim() : '';
}

function dispatchKeyEvent(world, element, key, code) {
  var event = new world.window.KeyboardEvent('keydown', {
    key: key, keyCode: code, which: code, bubbles: true, cancelable: true
  });
  element.dispatchEvent(event);
}

function dispatchBlurEvent(world, element) {
  var event = new world.window.Event('blur', { bubbles: true, cancelable: false });
  element.dispatchEvent(event);
}

function dispatchDblClickEvent(world, element) {
  var event = new world.window.MouseEvent('dblclick', {
    bubbles: true, cancelable: true, view: world.window
  });
  element.dispatchEvent(event);
}

function dispatchClickEvent(world, element) {
  var event = new world.window.MouseEvent('click', {
    bubbles: true, cancelable: true, view: world.window
  });
  element.dispatchEvent(event);
}

function dispatchHashChangeEvent(world, oldURL, newURL) {
  var event = new world.window.HashChangeEvent('hashchange', {
    oldURL: oldURL, newURL: newURL, bubbles: true, cancelable: true
