function dispatchClickEvent(world, element) {
  var event = new world.window.MouseEvent('click', {
    bubbles: true, cancelable: true, view: world.window
  });
  element.dispatchEvent(event);
}

function dispatchHashChangeEvent(world, oldURL, newURL) {
  var event = new world.window.HashChangeEvent('hashchange', {
    oldURL: oldURL, newURL: newURL, bubbles: true, cancelable: true
  });
  world.window.dispatchEvent(event);
}

function seedLocalStorage(world, todos) {
  var stored = [];
  for (var i = 0; i < todos.length; i++) {
    stored.push({
      id: 'seed-' + i + '-' + Date.now(),
      title: todos[i].title,
      completed: todos[i].completed || false
    });
  }
  world.localStorage.setItem(world.STORAGE_KEY, JSON.stringify(stored));
}

function reloadApp(world, hash) {
  var win = world.setupWindow(hash || '#/');
  world.runAppCode();
}

// ----- Given steps -----

Given('the app is loaded fresh', function () {
  setupApp(this, '#/');
});

Given('the application starts at the {string} route', function (route) {
  setupApp(this, route);
});

Given('the following todos exist:', function (dataTable) {
  var rows = dataTable.hashes();
  var todos = [];
  for (var i = 0; i < rows.length; i++) {
    todos.push({
      title: rows[i].title,
      completed: rows[i].completed === 'true'
    });
  }
  seedLocalStorage(this, todos);
  reloadApp(this, this.window ? this.window.location.hash : '#/');
  var hash = this.window.location.hash || '#/';
  dispatchHashChangeEvent(this, 'http://localhost/', 'http://localhost/' + hash);
});

// ----- When steps -----

When('the user types {string} into the new-todo input and presses Enter', function (text) {
  var input = this.document.querySelector('.new-todo');
  assert(input, 'new-todo input not found');
  input.value = text;
  dispatchKeyEvent(this, input, 'Enter', 13);
});

When('the user clicks the toggle checkbox on {string}', function (title) {
  var item = findTodoItem(this, title);
  assert(item, 'Todo item "' + title + '" not found');
  var toggle = item.querySelector('.toggle');
  assert(toggle, 'Toggle checkbox not found for "' + title + '"');
  toggle.checked = !toggle.checked;
  dispatchClickEvent(this, toggle);
  var changeEvent = new this.window.Event('change', { bubbles: true });
  toggle.dispatchEvent(changeEvent);
