/**
 * TodoMVC Vanilla JS
 * @planks("the app is loaded fresh")
 * @planks("the application starts at the {string} route")
 * @planks("the following todos exist:")
 */

(function (window, document, localStorage) {
  'use strict';

  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoApp = {
    todos: [],
    filter: 'all',

    init: function () {
      this.load();
      this.filter = this.getFilterFromHash();
      this.render();
      this.bindEvents();
      window.addEventListener('hashchange', this.onHashChange.bind(this));
    },

    getFilterFromHash: function () {
      var hash = window.location.hash || '#/';
      if (hash === '#/active') return 'active';
      if (hash === '#/completed') return 'completed';
      return 'all';
    },

    load: function () {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        try {
          this.todos = JSON.parse(stored);
        } catch (e) {
          this.todos = [];
        }
      } else {
        this.todos = [];
      }
    },

    save: function () {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
    },

    addTodo: function (title) {
      var trimmed = title.trim();
      if (trimmed === '') return;
      this.todos.push({
        id: 'id_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
        title: trimmed,
        completed: false
      });
      this.save();
      this.render();
    },

    toggleTodo: function (id) {
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].completed = !this.todos[i].completed;
          break;
        }
      }
      this.save();
      this.render();
    },

    destroyTodo: function (id) {
      var newTodos = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id !== id) {
          newTodos.push(this.todos[i]);
        }
      }
      this.todos = newTodos;
      this.save();
      this.render();
    },

    toggleAll: function (checked) {
      for (var i = 0; i < this.todos.length; i++) {
        this.todos[i].completed = checked;
      }
      this.save();
      this.render();
    },

    clearCompleted: function () {
      var active = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) {
          active.push(this.todos[i]);
        }
      }
      this.todos = active;
      this.save();
      this.render();
    },

    saveEdit: function (id, title) {
      var trimmed = title.trim();
      if (trimmed === '') {
        this.destroyTodo(id);
        return;
      }
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].title = trimmed;
          break;
        }
      }
      this.save();
      this.render();
    },

    cancelEdit: function () {
      this.render();
    },

    getFilteredTodos: function () {
      if (this.filter === 'active') {
        return this.todos.filter(function (t) { return !t.completed; });
      }
      if (this.filter === 'completed') {
        return this.todos.filter(function (t) { return t.completed; });
      }
      return this.todos;
    },

    getActiveCount: function () {
      var count = 0;
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) count++;
      }
      return count;
    },

    getCompletedCount: function () {
      return this.todos.length - this.getActiveCount();
    },

    render: function () {
      var list = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var toggleAll = document.getElementById('toggle-all');
      var todoCount = document.querySelector('.todo-count');
      var clearCompleted = document.querySelector('.clear-completed');
      var filters = document.querySelectorAll('.filters a');

      if (!list) return;

      // Show/hide main and footer based on whether there are todos
      if (this.todos.length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      } else {
        main.style.display = 'block';
        footer.style.display = 'block';
      }

      var filtered = this.getFilteredTodos();
      var html = '';
      for (var i = 0; i < filtered.length; i++) {
        var todo = filtered[i];
        var completedClass = todo.completed ? 'completed' : '';
        html += '<li class="' + completedClass + '" data-id="' + todo.id + '">';
        html += '<div class="view">';
        html += '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>';
        html += '<label>' + this.escapeHtml(todo.title) + '</label>';
        html += '<button class="destroy"></button>';
        html += '</div>';
        html += '<input class="edit" value="' + this.escapeHtml(todo.title) + '">';
        html += '</li>';
      }
      list.innerHTML = html;

      // Update toggle-all
      var allCompleted = this.todos.length > 0 && this.getActiveCount() === 0;
      toggleAll.checked = allCompleted;

      // Update count
      var activeCount = this.getActiveCount();
      var word = activeCount === 1 ? 'item' : 'items';
      todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

      // Show/hide clear completed
      if (this.getCompletedCount() > 0) {
        clearCompleted.style.display = 'block';
      } else {
        clearCompleted.style.display = 'none';
      }

      // Update filter links
      for (var f = 0; f < filters.length; f++) {
        var link = filters[f];
        var href = link.getAttribute('href');
        var filterName = 'all';
        if (href === '#/active') filterName = 'active';
        else if (href === '#/completed') filterName = 'completed';
        if (filterName === this.filter) {
          link.classList.add('selected');
        } else {
          link.classList.remove('selected');
        }
      }

      // Re-bind item events
      this.bindItemEvents();
    },

    bindEvents: function () {
      var self = this;
      var newTodo = document.querySelector('.new-todo');
      if (newTodo) {
        newTodo.addEventListener('keydown', function (e) {
          if (e.keyCode === ENTER_KEY) {
            self.addTodo(this.value);
            this.value = '';
          }
        });
      }

      var toggleAll = document.getElementById('toggle-all');
      if (toggleAll) {
        toggleAll.addEventListener('change', function () {
          self.toggleAll(this.checked);
        });
      }

      var clearBtn = document.querySelector('.clear-completed');
      if (clearBtn) {
        clearBtn.addEventListener('click', function () {
          self.clearCompleted();
        });
      }

      this.bindItemEvents();
    },

    bindItemEvents: function () {
      var self = this;
      var list = document.querySelector('.todo-list');
      if (!list) return;

      // Toggle
      var toggles = list.querySelectorAll('.toggle');
      for (var i = 0; i < toggles.length; i++) {
        toggles[i].addEventListener('change', function () {
          var li = this.closest('li');
          var id = li.getAttribute('data-id');
          self.toggleTodo(id);
        });
      }

      // Destroy
      var destroyBtns = list.querySelectorAll('.destroy');
      for (var j = 0; j < destroyBtns.length; j++) {
        destroyBtns[j].addEventListener('click', function () {
          var li = this.closest('li');
          var id = li.getAttribute('data-id');
          self.destroyTodo(id);
        });
      }

      // Double-click to edit
      var labels = list.querySelectorAll('label');
      for (var k = 0; k < labels.length; k++) {
        labels[k].addEventListener('dblclick', function () {
          var li = this.closest('li');
          var id = li.getAttribute('data-id');
          li.classList.add('editing');
          var editInput = li.querySelector('.edit');
          editInput.focus();
          editInput.value = editInput.value; // Set cursor at end
        });
      }

      // Edit input events
      var editInputs = list.querySelectorAll('.edit');
      for (var m = 0; m < editInputs.length; m++) {
        editInputs[m].addEventListener('keydown', function (e) {
          var li = this.closest('li');
          var id = li.getAttribute('data-id');
          if (e.keyCode === ENTER_KEY) {
            self.saveEdit(id, this.value);
          } else if (e.keyCode === ESCAPE_KEY) {
            li.classList.remove('editing');
            self.cancelEdit();
          }
        });
        editInputs[m].addEventListener('blur', function () {
          var li = this.closest('li');
          if (!li) return;
          var id = li.getAttribute('data-id');
          // Give priority to Enter keydown
          setTimeout(function () {
            if (li.classList.contains('editing')) {
              self.saveEdit(id, editInputs[m].value);
            }
          }, 0);
        });
      }
    },

    onHashChange: function () {
      this.filter = this.getFilterFromHash();
      this.render();
    },

    escapeHtml: function (text) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(text));
      return div.innerHTML;
    }
  };

  // Expose for testing
  window.todoApp = todoApp;

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      todoApp.init();
    });
  } else {
    todoApp.init();
  }
})(window, document, localStorage);

